// cpp-httplib first and alone: no JUCE headers in this file (see ApiServer.h).
#include <httplib.h>

#include "api/ApiServer.h"

#include <ClientScript.h> // examples/carrilion-client.js, generated by CMakeLists.txt

#include <condition_variable>
#include <deque>
#include <mutex>
#include <set>
#include <thread>

namespace vstplayer::api
{

namespace
{
constexpr size_t kMaxPayload = 16 * 1024 * 1024;
constexpr int kWebSocketPollMs = 250; // read timeout: how often a WebSocket loop checks for stop()

const char* const kJsonType = "application/json; charset=utf-8";
const char* const kUnauthorized = R"({"ok":false,"code":"unauthorized","error":"Token incorrecto o ausente (?token=...)."})";
} // namespace

struct ApiServer::Impl
{
    httplib::Server server;
    std::thread listenThread;
    RequestHandler handler;
    std::string token;
    std::atomic<bool> running { false };
    std::atomic<bool> stopping { false };
    std::atomic<long long> numRequests { 0 };

    mutable std::mutex socketsLock;
    std::set<httplib::ws::WebSocket*> sockets;

    std::function<void()>* onClientsChanged = nullptr;

    // Pushed events go through a queue and a sender thread, so a slow client never blocks the
    // thread that produced the event (usually the message thread).
    std::thread senderThread;
    std::mutex queueLock;
    std::condition_variable queueCondition;
    std::deque<std::string> queue;
    static constexpr size_t kMaxQueued = 2000;

    void senderLoop()
    {
        for (;;)
        {
            std::string text;

            {
                std::unique_lock<std::mutex> l (queueLock);
                queueCondition.wait (l, [this] { return stopping.load() || ! queue.empty(); });

                if (stopping.load())
                    return;

                text = std::move (queue.front());
                queue.pop_front();
            }

            std::lock_guard<std::mutex> l (socketsLock);

            for (auto* ws : sockets)
                ws->send (text);
        }
    }

    bool tokenOk (const httplib::Request& req) const
    {
        if (token.empty())
            return true;

        if (req.has_param ("token") && req.get_param_value ("token") == token)
            return true;

        return req.has_header ("X-Api-Token") && req.get_header_value ("X-Api-Token") == token;
    }

    void answer (const std::string& body, httplib::Response& res)
    {
        numRequests.fetch_add (1);
        const auto r = handler (body);
        res.status = r.status;
        res.set_content (r.body, kJsonType);
    }

    void clientsChanged()
    {
        if (onClientsChanged != nullptr && *onClientsChanged)
            (*onClientsChanged)();
    }

    void handleWebSocket (const httplib::Request& req, httplib::ws::WebSocket& ws)
    {
        if (! tokenOk (req))
        {
            ws.send (kUnauthorized);
            ws.close (httplib::ws::CloseStatus::PolicyViolation, "token");
            return;
        }

        {
            std::lock_guard<std::mutex> l (socketsLock);
            sockets.insert (&ws);
        }
        clientsChanged();

        ws.set_read_timeout (std::chrono::milliseconds (kWebSocketPollMs));
        std::string message;

        while (! stopping.load() && ws.is_open())
        {
            const auto result = ws.read (message);

            if (result == httplib::ws::Timeout)
                continue;

            if (result == httplib::ws::Fail)
                break;

            if (result == httplib::ws::Binary)
            {
                ws.send (R"({"ok":false,"code":"badRequest","error":"Sólo se aceptan mensajes de texto (JSON)."})");
                continue;
            }

            numRequests.fetch_add (1);
            const auto r = handler (message);

            if (! ws.send (r.body))
                break;
        }

        {
            std::lock_guard<std::mutex> l (socketsLock);
            sockets.erase (&ws);
        }

        if (stopping.load())
            ws.close (httplib::ws::CloseStatus::GoingAway, "server stopping");
        else
            clientsChanged();
    }
};

ApiServer::ApiServer() : impl (std::make_unique<Impl>()) {}

ApiServer::~ApiServer()
{
    stop();
}

bool ApiServer::start (const std::string& host, int port, const std::string& token, RequestHandler handler, std::string& error)
{
    stop();

    impl = std::make_unique<Impl>();
    impl->handler = std::move (handler);
    impl->token = token;
    impl->onClientsChanged = &onClientsChanged;

    auto& server = impl->server;
    auto* d = impl.get();

    server.set_payload_max_length (kMaxPayload);
    server.set_default_headers ({ { "Access-Control-Allow-Origin", "*" },
                                  { "Access-Control-Allow-Methods", "GET, POST, OPTIONS" },
                                  { "Access-Control-Allow-Headers", "Content-Type, X-Api-Token" },
                                  { "Access-Control-Allow-Private-Network", "true" },
                                  { "Cache-Control", "no-store" } });

    // Token check before routing (the CORS preflight never carries it; the WebSocket handler
    // checks it itself so the browser gets a readable message).
    server.set_pre_routing_handler ([d] (const httplib::Request& req, httplib::Response& res)
    {
        if (req.method == "OPTIONS" || req.path == "/client.js" || req.has_header ("Upgrade") || d->tokenOk (req))
            return httplib::Server::HandlerResponse::Unhandled;

        res.status = 401;
        res.set_content (kUnauthorized, kJsonType);
        return httplib::Server::HandlerResponse::Handled;
    });

    server.Options (".*", [] (const httplib::Request&, httplib::Response& res) { res.status = 204; });

    server.Post ("/api", [d] (const httplib::Request& req, httplib::Response& res) { d->answer (req.body, res); });
    server.Get ("/api/status", [d] (const httplib::Request&, httplib::Response& res) { d->answer (R"({"cmd":"status"})", res); });
    server.Get ("/client.js", [] (const httplib::Request&, httplib::Response& res)
    {
        res.set_content (std::string (reinterpret_cast<const char*> (kClientScript), sizeof (kClientScript)), "text/javascript; charset=utf-8");
    });
    server.Get ("/", [] (const httplib::Request&, httplib::Response& res)
    {
        res.set_content (R"({"name":"VstPlayer","api":1,"http":"POST /api","websocket":"/ws","client":"/client.js"})", kJsonType);
    });

    const auto wsHandler = [d] (const httplib::Request& req, httplib::ws::WebSocket& ws) { d->handleWebSocket (req, ws); };
    server.WebSocket ("/", wsHandler);
    server.WebSocket ("/ws", wsHandler);

    server.set_error_handler ([] (const httplib::Request&, httplib::Response& res)
    {
        if (res.body.empty())
            res.set_content (R"({"ok":false,"code":"notFound","error":"Ruta desconocida: usar POST /api o WebSocket /ws."})", kJsonType);
    });

    if (! server.bind_to_port (host, port))
    {
        error = "no se pudo abrir " + host + ":" + std::to_string (port) + " (¿puerto ocupado?)";
        impl = std::make_unique<Impl>();
        return false;
    }

    impl->running = true;
    impl->listenThread = std::thread ([d] { d->server.listen_after_bind(); });
    impl->senderThread = std::thread ([d] { d->senderLoop(); });
    return true;
}

void ApiServer::stop()
{
    if (impl == nullptr || ! impl->running.load())
        return;

    // The WebSocket loops notice within kWebSocketPollMs and close their sockets themselves.
    impl->stopping = true;

    {
        std::lock_guard<std::mutex> l (impl->queueLock);
        impl->queueCondition.notify_all();
    }

    if (impl->senderThread.joinable())
        impl->senderThread.join();

    impl->server.stop();

    if (impl->listenThread.joinable())
        impl->listenThread.join();

    impl->running = false;
}

bool ApiServer::isRunning() const noexcept
{
    return impl != nullptr && impl->running.load();
}

int ApiServer::getNumClients() const noexcept
{
    if (impl == nullptr)
        return 0;

    std::lock_guard<std::mutex> l (impl->socketsLock);
    return (int) impl->sockets.size();
}

long long ApiServer::getNumRequests() const noexcept
{
    return impl != nullptr ? impl->numRequests.load() : 0;
}

void ApiServer::broadcast (const std::string& text)
{
    if (impl == nullptr || ! impl->running.load())
        return;

    {
        std::lock_guard<std::mutex> l (impl->socketsLock);

        if (impl->sockets.empty())
            return;
    }

    std::lock_guard<std::mutex> l (impl->queueLock);

    if (impl->queue.size() >= Impl::kMaxQueued)
        impl->queue.pop_front(); // a stuck client: drop the oldest event

    impl->queue.push_back (text);
    impl->queueCondition.notify_one();
}

} // namespace vstplayer::api
